<script setup lang="ts">
type Winner={id:string;name:string;difficulty:string;completionTime:number;moves:number;claimCode:string;wonAt:string;claimed:boolean;claimedAt:string|null}
const pin=ref(''); const loggedIn=ref(false); const winners=ref<Winner[]>([]); const search=ref(''); const message=ref(''); const busy=ref(false)
const filtered=computed(()=>{const q=search.value.trim().toLowerCase(); return !q?winners.value:winners.value.filter(w=>w.name.toLowerCase().includes(q)||w.claimCode.toLowerCase().includes(q))})
function fmt(s:number){return s<60?`${s}s`:`${Math.floor(s/60)}m ${s%60}s`}
async function load(){message.value=''; try{winners.value=await $fetch('/api/admin/winners',{query:{pin:pin.value}});loggedIn.value=true}catch{loggedIn.value=false;message.value='Invalid admin PIN.'}}
async function claim(w:Winner){if(w.claimed)return; busy.value=true;message.value='';try{const r:any=await $fetch('/api/admin/claim',{method:'POST',body:{pin:pin.value,claimCode:w.claimCode}});message.value=r.alreadyClaimed?'⚠️ Candy was already claimed.':'✅ Candy marked as claimed.';await load()}catch(e:any){message.value=e?.data?.statusMessage||'Unable to claim candy.'}finally{busy.value=false}}
async function resetAll(){if(!confirm('Delete ALL winner records? This cannot be undone.'))return; const confirmation=prompt('Type RESET to confirm:');if(confirmation!=='RESET')return;await $fetch('/api/admin/reset',{method:'POST',body:{pin:pin.value,confirm:'RESET'}});message.value='Winner records reset.';await load()}
</script>
<template><main class="app-shell"><header class="header"><div class="brand">🍬 CANDY <span>ADMIN</span></div><NuxtLink class="leader-link" to="/">🚗 Game</NuxtLink></header><section class="panel admin-panel"><template v-if="!loggedIn"><p class="eyebrow">CANDY STATION</p><h1>Admin <span>Login</span></h1><form class="setup" @submit.prevent="load"><label>ADMIN PIN</label><input v-model="pin" type="password" inputmode="numeric" placeholder="Enter admin PIN"><p v-if="message" class="error">{{message}}</p><button class="primary">🔐 OPEN ADMIN</button></form></template><template v-else><p class="eyebrow">CANDY STATION</p><h1>Winner <span>Claims</span></h1><input v-model="search" class="admin-search" placeholder="Search name or CANDY code"><p v-if="message" class="admin-message">{{message}}</p><div class="admin-actions"><button class="text-button" @click="load">🔄 Refresh</button><NuxtLink class="leader-link" to="/leaderboard">🏆 Top 5</NuxtLink><button class="text-button danger" @click="resetAll">🗑 Reset Event</button></div><div class="winner-list"><article v-for="w in filtered" :key="w.id" class="winner-card" :class="{claimed:w.claimed}"><div><strong>{{w.name}}</strong><small>{{w.difficulty.toUpperCase()}} · {{fmt(w.completionTime)}} · {{w.moves}} moves</small><code>{{w.claimCode}}</code></div><button :disabled="w.claimed||busy" @click="claim(w)">{{w.claimed?'✅ CLAIMED':'🍬 CLAIM CANDY'}}</button></article><p v-if="!filtered.length" class="small-note">No matching winners.</p></div></template></section></main></template>
